// Mutants & Masterminds 3e equipment that is NOT Hero SRD content.
//
// WHAT THIS FILE IS. Until this module existed, the mam3e equipment data was 150
// hand-written entries, every one of them tagged `source: "Hero's Handbook"`.
// Only 45 of those names appear in the Hero SRD at all. Of the remaining 104, 25
// were the SRD's own items under a different name (`Sedan` for `Car (Sedan)`,
// `Laser Pistol` for `Blaster Pistol`, `House` for `HQ: Size – Small (house)`, …)
// and have been reconciled to the SRD entry, which is now generated by
// scripts/encode-mam-equipment.mjs. The 79 entries below are the rest: original
// content authored for this application with no Hero SRD counterpart at all.
//
// WHY THEY ARE STILL HERE. Removing shipped content is the repository owner's
// call, not an audit's. Nothing is deleted. What changed is the citation: these
// entries no longer claim a book they were never transcribed from. A false
// attribution is a defect, not a preference — that is the whole finding.
//
// `MAM3E_ORIGINAL_SOURCE` is NOT open-content provenance and is deliberately
// kept off `strictOpenContentPolicy.allowedSources`. It is admitted through the
// separate `originalContentSources` channel in src/utils/openContentPolicy.ts,
// so the distinction between "transcribed from an open document" and "written
// for this app" stays machine-readable instead of being smuggled into the
// open-content whitelist.
//
// The item-by-item classification (which entry was reconciled to which SRD row,
// and which was kept here) is recorded in docs/mam3e-equipment-provenance.md.
//
// Unlike ./srd-*.ts this file is HAND-WRITTEN and stays hand-written: there is
// no upstream to encode it from. Its stat blocks are unaudited by construction —
// there is nothing to audit them against.

import { Device, Headquarters, MaMEquipment, Vehicle } from '../../../../types/mam/equipment';

/**
 * Source label for equipment authored for this application rather than
 * transcribed from the M&M 3e Hero SRD. Kept as a constant so the gate
 * (scripts/check-mam-equipment-provenance.mjs) and the open-content policy
 * cannot drift from the data.
 */
export const MAM3E_ORIGINAL_SOURCE = 'Original Content (not SRD)';

export interface MaMArmor extends MaMEquipment {
  type: 'armor';
  protection: number;
  penalty?: number;
}

export interface MaMWeapon extends MaMEquipment {
  type: 'weapon';
  damage: number;
  damageType: 'bludgeoning' | 'piercing' | 'slashing' | 'ballistic' | 'energy';
  range: 'close' | 'ranged';
  critical?: number;
}

